import Database from 'better-sqlite3';
import { drizzle } from 'drizzle-orm/better-sqlite3';
import * as schema from './schema.js';

const DB_FILE = process.env.DATABASE_FILE ?? 'invoices.db';

export const sqlite = new Database(DB_FILE);
sqlite.pragma('journal_mode = WAL');
sqlite.pragma('foreign_keys = ON');

export const db = drizzle(sqlite, { schema });
export { schema };

/**
 * Creates the tables if they are not already there.
 *
 * Deliberately hand-written rather than generated by drizzle-kit: the whole
 * schema is two tables, and keeping the DDL visible in the repo means the
 * reviewer can read the real SQL without running a migration tool. For anything
 * larger this would be a versioned migration directory instead.
 */
export function initialiseSchema() {
  sqlite.exec(`
    CREATE TABLE IF NOT EXISTS invoices (
      id                TEXT PRIMARY KEY,
      vendor_name       TEXT NOT NULL,
      invoice_number    TEXT NOT NULL,
      amount_cents      INTEGER NOT NULL,
      currency          TEXT NOT NULL DEFAULT 'USD',
      invoice_date      INTEGER NOT NULL,
      due_date          INTEGER,
      description       TEXT,
      status            TEXT NOT NULL DEFAULT 'processing'
                        CHECK (status IN ('processing','needs_review','approved','rejected')),
      duplicate_of_id   TEXT REFERENCES invoices(id),
      duplicate_reason  TEXT,
      created_at        INTEGER NOT NULL DEFAULT (unixepoch()),
      updated_at        INTEGER NOT NULL DEFAULT (unixepoch())
    );

    CREATE INDEX IF NOT EXISTS invoices_status_idx     ON invoices(status);
    CREATE INDEX IF NOT EXISTS invoices_vendor_ref_idx ON invoices(vendor_name, invoice_number);

    CREATE TABLE IF NOT EXISTS status_events (
      id          TEXT PRIMARY KEY,
      invoice_id  TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
      from_status TEXT CHECK (from_status IN ('processing','needs_review','approved','rejected')),
      to_status   TEXT NOT NULL
                  CHECK (to_status IN ('processing','needs_review','approved','rejected')),
      reason      TEXT,
      actor       TEXT NOT NULL DEFAULT 'reviewer',
      created_at  INTEGER NOT NULL DEFAULT (unixepoch())
    );

    CREATE INDEX IF NOT EXISTS status_events_invoice_created_idx
      ON status_events(invoice_id, created_at);
  `);
}

/** Short collision-resistant id. No uuid dependency needed for six rows. */
export function newId(prefix = 'inv'): string {
  return `${prefix}_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
}
